package com.hbm.satellite.cargo.client;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.satellite.cargo.SatelliteDockMenu;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.resources.language.I18n;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.player.Inventory;import java.util.Arrays;
/** Exact source176x186 cargo return GUI,15takeonly slots and one real Chip slot; original titlecenter115. */
public final class SatelliteDockScreen extends LegacyContainerScreen<SatelliteDockMenu>{
 private static final ResourceLocation TEXTURE=ResourceLocation.parse("hbm:textures/gui/storage/gui_sat_dock.png"),UTILITY=ResourceLocation.parse("hbm:textures/gui/gui_utility.png");public SatelliteDockScreen(SatelliteDockMenu menu,Inventory inventory,Component title){super(menu,inventory,title,TEXTURE,176,186);}@Override protected void renderBg(GuiGraphics graphics,float partial,int mx,int my){super.renderBg(graphics,partial,mx,my);graphics.blit(UTILITY,leftPos-7,topPos+36,8,0,16,16);}@Override protected void renderLabels(GuiGraphics graphics,int mx,int my){var name=menu.machine.getDisplayName();graphics.drawString(font,name,115-font.width(name)/2,6,0x404040,false);graphics.drawString(font,playerInventoryTitle,8,92,0x404040,false);}@Override public void render(GuiGraphics graphics,int mx,int my,float partial){super.render(graphics,mx,my,partial);renderTooltip(graphics,mx,my);if(legacyInfoHovered(mx,my,-7,36,16,16))graphics.renderComponentTooltip(font,Arrays.stream(I18n.get("desc.gui.satdock.desc").split("\\$",-1)).map(line->(Component)Component.literal(line)).toList(),mx,my);}
}
